using Acme.Weather;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddSingleton<WeatherClient>();
builder.Services.AddSingleton<ForecastCache>();

var app = builder.Build();

app.MapGet("/forecast/{city}", async (string city, ForecastCache forecasts, CancellationToken ct) =>
    await forecasts.GetAsync(city, ct) is { } forecast
        ? Results.Ok(forecast)
        : Results.NotFound());

app.Run();

using System.Net.Http.Json;

namespace Acme.Weather;

public sealed class WeatherClient
{
    public async Task<Forecast?> GetAsync(string city, CancellationToken ct)
    {
        using var http = new HttpClient();
        http.BaseAddress = new Uri("https://api.example.com/");
        return await http.GetFromJsonAsync<Forecast>($"v1/forecast?city={Uri.EscapeDataString(city)}", ct);
    }
}

public sealed record Forecast(string City, double TemperatureC);

using System.Collections.Concurrent;

namespace Acme.Weather;

public sealed class ForecastCache(WeatherClient weather)
{
    private readonly ConcurrentDictionary<string, Forecast> _latest = new();

    public async Task<Forecast?> GetAsync(string city, CancellationToken ct)
    {
        if (_latest.TryGetValue(city, out var cached)) return cached;

        var forecast = await weather.GetAsync(city, ct);
        if (forecast is not null) _latest[city] = forecast;
        return forecast;
    }
}

